def format_bytes(n):
    """Return a human-readable size such as '1.5 KB'."""
    steps = ["B", "KB", "MB", "GB", "TB"]
    size = float(n)
    for unit in steps[:-1]:
        if size < 1024.0:
            return f"{size:.1f} {unit}"
        size /= 1024.0
    return f"{size:.1f} {steps[-1]}"
